SELECT p.gender, CAST(COUNT(DISTINCT CASE WHEN e.charttime BETWEEN a.admittime AND a.admittime + INTERVAL '48 hours' THEN e.itemid END) AS FLOAT) / NULLIF(COUNT(DISTINCT CASE WHEN e.charttime BETWEEN a.dischtime - INTERVAL '12 hours' AND a.dischtime THEN e.itemid END), 0) AS proportion_first_48h, CAST(COUNT(DISTINCT CASE WHEN e.charttime BETWEEN a.dischtime - INTERVAL '12 hours' AND a.dischtime THEN e.itemid END) AS FLOAT) / NULLIF(COUNT(DISTINCT CASE WHEN e.charttime BETWEEN a.admittime AND a.admittime + INTERVAL '48 hours' THEN e.itemid END), 0) AS proportion_last_12h, (proportion_first_48h - proportion_last_12h) AS net_change FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN labevents e ON a.subject_id = e.subject_id AND a.hadm_id = e.hadm_id WHERE p.gender = 'F' AND p.anchor_age BETWEEN 68 AND 78 AND a.dischtime IS NOT NULL AND e.valueuom = 'g' AND e.value IS NOT NULL AND (e.itemid = 1507170 OR e.itemid = 1507171 OR e.itemid = 1507172 OR e.itemid = 1507173) GROUP BY p.gender;